    fun getTitleMap(lang: String): Map<String, String> {
        return when (lang) {
            "en" -> EnglishTitles.map
            "de" -> deTitles.map
            "fr" -> frTitles.map
            "pt" -> ptTitles.map
            "zh" -> zhTitles.map
